+import React from "react";
+import classNames from "classnames";
+
+import { ContextMenuButton, useContextMenu } from "../../structures/ContextMenu";
+import IconizedContextMenu, { IconizedContextMenuOptionList } from "./IconizedContextMenu";
+
+interface Props extends Omit<React.ComponentProps<typeof ContextMenuButton>,
+    "label" | "isExpanded" | "onClick" | "children"> {
+    options: React.ReactNode[];
+    title: string;
+}
+
+export const KebabContextMenu: React.FC<Props> = ({ options, title, disabled, className, ...props }) => {
+    const [isOpen, buttonRef, open, close] = useContextMenu<HTMLElement>();
+    const buttonRect = isOpen ? buttonRef.current?.getBoundingClientRect() : undefined;
+
+    const onOpen = (ev: React.SyntheticEvent) => {
+        // ContextMenu restores focus to the element which was active when it opened.
+        buttonRef.current?.focus();
+        open(ev);
+    };
+
+    // AccessibleButton calls onClick directly for Enter and Space, so those
+    // activations do not produce a click that can reach ContextMenu's wrapper.
+    const menuOptions = React.Children.map(options, option => {
+        if (!React.isValidElement<{ onClick?: (ev: React.SyntheticEvent) => void }>(option)) return option;
+        const onClick = option.props.onClick;
+        if (!onClick) return option;
+
+        return React.cloneElement(option, {
+            onClick: (ev: React.SyntheticEvent) => {
+                onClick(ev);
+                if (ev.type !== "click") close();
+            },
+        });
+    });
+
+    return <>
+        <ContextMenuButton
+            {...props}
+            inputRef={buttonRef}
+            label={title}
+            isExpanded={isOpen}
+            disabled={disabled}
+            onClick={onOpen}
+            className={classNames("mx_KebabContextMenu_trigger", className)}
+        >
+            <span className="mx_KebabContextMenu_icon" aria-hidden="true" />
+        </ContextMenuButton>
+        { isOpen && buttonRect && <IconizedContextMenu
+            left={buttonRect.right + window.scrollX}
+            top={buttonRect.bottom + window.scrollY}
+            rightAligned
+            onFinished={close}
+            className="mx_KebabContextMenu_menu"
+        >
+            <IconizedContextMenuOptionList red>
+                { menuOptions }
+            </IconizedContextMenuOptionList>
+        </IconizedContextMenu> }
+    </>;
+};
